// build-node-bundles.js — assemble paste-ready n8n Code-node scripts.
//   npm run build:nodes
//
// Keeps CLAUDE.md's rule honest: the logic lives once in scripts/. This tool inlines
// that source verbatim (stripping ES `import`/`export` so it runs as a plain script)
// into each thin wrapper's __CORE__ marker. The wrappers hold only n8n glue. Never
// hand-edit the *.built.js output — edit scripts/ or the *.wrapper.js and re-run.

import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const nodesDir = join(root, 'workflows', 'code-nodes');

// Which scripts each node needs, in dependency order.
const NODES = {
  validate: ['dates.js', 'expandTemplates.js', 'validate.js'],
  expandTemplates: ['dates.js', 'expandTemplates.js'],
  notify: ['notify.js'],
  completeParse: ['notify.js'],
  completeResolve: ['notify.js'],
  completeCheck: ['notify.js'],
  completeRender: ['notify.js'],
};

/** Strip ESM `import`/`export` so the module body runs as a plain script. */
function toPlainScript(source) {
  return source
    .split('\n')
    .filter((line) => !/^\s*import\b/.test(line))
    .map((line) => line.replace(/^export\s+/, ''))
    .join('\n')
    .trim();
}

for (const [node, files] of Object.entries(NODES)) {
  const core = files
    .map((f) => `// ---- inlined from scripts/${f} ----\n${toPlainScript(readFileSync(join(root, 'scripts', f), 'utf8'))}`)
    .join('\n\n');

  const wrapper = readFileSync(join(nodesDir, `${node}.wrapper.js`), 'utf8');
  if (!wrapper.includes('/* __CORE__ */')) {
    throw new Error(`${node}.wrapper.js is missing the /* __CORE__ */ marker`);
  }

  const header =
    `// ============================================================================\n` +
    `// GENERATED by \`npm run build:nodes\` — DO NOT EDIT.\n` +
    `// Wrapper: workflows/code-nodes/${node}.wrapper.js\n` +
    `// Core inlined verbatim from: ${files.map((f) => `scripts/${f}`).join(', ')}\n` +
    `// Paste this whole file into the n8n Code node.\n` +
    `// ============================================================================\n\n`;

  const built = header + wrapper.replace('/* __CORE__ */', core);
  writeFileSync(join(nodesDir, `${node}.built.js`), built);
  console.log(`built workflows/code-nodes/${node}.built.js  (${files.join(' + ')} + wrapper)`);
}
